/**
 * Real user profile built from the bundled Letterboxd export
 * (see shared/letterboxd-data.js, generated by tools/build-letterboxd-profile.mjs).
 *
 * This replaces the old seeded mock profile. Every band/reason cites the
 * user's actual ratings, rewatches, reviews, or watchlist — never invented
 * traits. Same result shape as before ({ band, score, reason }).
 */

globalThis.CineGraphLetterboxdProfile = (() => {
  const STOPWORDS = new Set([
    "the", "a", "an", "of", "and", "in", "on", "to", "for", "vs", "v",
    "part", "volume", "vol", "chapter", "episode", "movie", "film",
    "ki", "ka", "ke", "aur", "ek", "main", "hai", "se", "ko",
    "your", "you", "my", "me", "our", "we", "him", "her", "his", "its",
    "this", "that", "with", "from", "into", "over", "under",
    "will", "would", "could", "should", "shall", "may", "might", "must", "can",
  ]);

  function norm(s) {
    return String(s || "")
      .toLowerCase()
      .normalize("NFKD")
      .replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, " ")
      .trim()
      .replace(/\s+/g, " ");
  }

  function tokens(s) {
    return norm(s).split(" ").filter((t) => t.length >= 4 && !STOPWORDS.has(t));
  }

  function data() {
    return globalThis.CineGraphLetterboxdData || null;
  }

  function ratingIndex() {
    const d = data();
    const idx = new Map();
    if (!d) return idx;
    for (const r of d.ratings || []) {
      const k = `${norm(r.title)}|||${r.year ?? ""}`;
      if (!idx.has(k)) idx.set(k, r);
      const tk = norm(r.title);
      if (!idx.has(tk)) idx.set(tk, r);
      else if (Array.isArray(idx.get(tk))) idx.get(tk).push(r);
      else idx.set(tk, [idx.get(tk), r]);
    }
    return idx;
  }

  let _ratingIndex = null;
  function findRating(title, year = null) {
    if (!_ratingIndex) _ratingIndex = ratingIndex();
    const t = norm(title);
    if (!t) return null;
    if (year != null) {
      const hit = _ratingIndex.get(`${t}|||${year}`);
      if (hit && !Array.isArray(hit)) return hit;
    }
    const hit = _ratingIndex.get(t);
    if (!hit) return null;
    if (Array.isArray(hit)) {
      if (year != null) return hit.find((r) => r.year === year) || null;
      return hit.slice().sort((a, b) => (b.rating ?? 0) - (a.rating ?? 0))[0];
    }
    return hit;
  }

  function diaryEntry(title, year = null) {
    const d = data();
    if (!d) return null;
    const t = norm(title);
    const hits = (d.diary || []).filter(
      (e) => norm(e.title) === t && (year == null || e.year === year)
    );
    return hits[0] || null;
  }

  function watchlistEntry(title, year = null) {
    const d = data();
    if (!d) return null;
    const t = norm(title);
    return (d.watchlist || []).find(
      (w) => norm(w.title) === t && (year == null || w.year === year || w.year == null)
    ) || null;
  }

  function likedTitles(minRating = 4.5) {
    const d = data();
    if (!d) return [];
    return (d.ratings || []).filter((r) => (r.rating ?? 0) >= minRating);
  }

  function dislikedTitles(maxRating = 2) {
    const d = data();
    if (!d) return [];
    return (d.ratings || []).filter((r) => (r.rating ?? 99) <= maxRating);
  }

  function firstWord(s) {
    const parts = norm(s).split(" ").filter((t) => !STOPWORDS.has(t));
    return parts[0] || "";
  }

  /** First two significant words — strict series signal ("spider man"). */
  function firstTwo(s) {
    const parts = norm(s).split(" ").filter((t) => !STOPWORDS.has(t) && t.length >= 3);
    return parts.length >= 2 ? `${parts[0]} ${parts[1]}` : null;
  }

  /** Text before a colon ("Avengers" in "Avengers: Doomsday"), stopwords off. */
  function colonPrefix(s) {
    const i = String(s || "").indexOf(":");
    if (i <= 0) return null;
    const parts = norm(s.slice(0, i)).split(" ").filter((t) => !STOPWORDS.has(t));
    return parts.length ? parts : null;
  }

  /**
   * Strict franchise test: same two-word opening, or same colon-series
   * prefix ("Avengers: X" ≈ "Avengers: Y"). Single shared words like
   * "Iron", "Good", or "Your" do NOT count — they caused false series
   * links (Iron Lung ≠ Iron Man).
   */
  function isSameSeries(a, b) {
    if (norm(a) === norm(b)) return true;
    const ta = firstTwo(a);
    const tb = firstTwo(b);
    if (ta && tb && ta === tb) return true;
    const ca = colonPrefix(a);
    const cb = colonPrefix(b);
    if (ca && cb && ca[0] === cb[0] && ca[0].length >= 4) return true;
    if (ca && !cb) {
      const fb = norm(b).split(" ").filter((t) => !STOPWORDS.has(t));
      if (ca[0] === fb[0] && (ca[1] ? ca[1] === fb[1] : true) && ca[0].length >= 4) return true;
    }
    if (cb && !ca) {
      const fa = norm(a).split(" ").filter((t) => !STOPWORDS.has(t));
      if (cb[0] === fa[0] && (cb[1] ? cb[1] === fa[1] : true) && cb[0].length >= 4) return true;
    }
    return false;
  }

  /**
   * Score a title against the real Letterboxd library.
   * Priority: own rating > franchise of a liked film > token affinity >
   * watchlist membership > honest no-signal fallback.
   */
  function scoreTitle(rawTitle, year = null) {
    const title = String(rawTitle || "").trim();
    const d = data();
    if (!title) return null;
    if (!d) {
      return { band: "Possible Match", score: 0.3, reason: "Library not loaded yet." };
    }

    // 1. The user already rated this exact film — their own verdict wins.
    const own = findRating(title, year);
    if (own?.rating != null) {
      const entry = diaryEntry(title, own.year);
      const extra = entry?.rewatch ? " You rewatched it." : "";
      const reviewBit = entry?.review ? ` You wrote: "${entry.review.slice(0, 120)}${entry.review.length > 120 ? "…" : ""}"` : "";
      if (own.rating >= 4) {
        return {
          band: "Strong Match",
          score: own.rating / 5,
          reason: `You rated this ${own.rating}★ on Letterboxd.${extra}${reviewBit}`,
        };
      }
      if (own.rating >= 3) {
        return {
          band: "Possible Match",
          score: own.rating / 5,
          reason: `You rated this ${own.rating}★ on Letterboxd — middle of the road for you.${extra}`,
        };
      }
      return {
        band: "Weak Match",
        score: own.rating / 5,
        reason: `You rated this ${own.rating}★ on Letterboxd — below your ${d.stats?.avgRating ?? ""}★ average.`,
      };
    }

    const toks = new Set(tokens(title));
    const fw = firstWord(title);
    let score = 0;
    const evidence = [];

    // 2. Franchise / same-series as a film they loved (4.5★+).
    for (const liked of likedTitles(4.5)) {
      if (norm(liked.title) === norm(title)) continue;
      if (isSameSeries(title, liked.title)) {
        score += 1.3;
        evidence.push(`same series as ${liked.title} (your ${liked.rating}★)`);
        break;
      }
    }

    // 3. Token affinity with 4.5★+ films.
    let bestTokenHit = null;
    let bestTokenCount = 0;
    for (const liked of likedTitles(4.5)) {
      const lt = new Set(tokens(liked.title));
      let shared = 0;
      for (const t of toks) if (lt.has(t)) shared += 1;
      if (shared > bestTokenCount) {
        bestTokenCount = shared;
        bestTokenHit = liked;
      }
    }
    if (bestTokenCount > 0 && bestTokenHit) {
      score += bestTokenCount * 0.45;
      evidence.push(`shares ${bestTokenCount > 1 ? "themes" : "a theme"} with ${bestTokenHit.title} (your ${bestTokenHit.rating}★)`);
    }

    // 4. Cold drag: overlaps films they rated 2★ or less.
    for (const cold of dislikedTitles(2)) {
      const lt = new Set(tokens(cold.title));
      let shared = 0;
      for (const t of toks) if (lt.has(t)) shared += 1;
      if (isSameSeries(title, cold.title) || shared >= 2) {
        score -= 0.9;
        evidence.push(`echoes ${cold.title} (your ${cold.rating}★)`);
        break;
      }
    }

    // 5. It's sitting on their watchlist — explicit intent.
    const wl = watchlistEntry(title, year);
    if (wl) {
      score += 0.5;
      evidence.push(`on your watchlist${wl.addedDate ? ` since ${wl.addedDate}` : ""}`);
    }

    const band = score >= 1.3 ? "Strong Match" : score >= 0.6 ? "Possible Match" : "Weak Match";
    const rounded = Math.round(Math.max(0, Math.min(1, 0.35 + score / 4)) * 100) / 100;

    // Queued intent floors at Possible: being on the watchlist is never a
    // Weak signal, even without token overlap.
    if (wl && band === "Weak Match") {
      return {
        band: "Possible Match",
        score: Math.max(rounded, 0.45),
        reason: `On your watchlist${wl.addedDate ? ` since ${wl.addedDate}` : ""} — no strong link to your rated films yet.`,
      };
    }

    if (!evidence.length) {
      const anchor = (d.favorites || [])[0];
      return {
        band: "Possible Match",
        score: 0.3,
        reason: anchor
          ? `Not in your rated films — closest anchor is your favourite ${anchor.title} (${anchor.year}).`
          : "Not in your rated films yet.",
      };
    }

    const anchor = evidence[0];
    const reason =
      band === "Strong Match"
        ? `Strong link to your library: ${anchor}.`
        : band === "Possible Match"
          ? `Partial link to your library: ${anchor}.`
          : `Weak link to your library: ${anchor}.`;
    return { band, score: rounded, reason };
  }

  /** Rank the user's unrated watchlist by predicted affinity. */
  function rankWatchlist(limit = 8) {
    const d = data();
    if (!d) return [];
    const scored = (d.watchlist || []).map((w) => {
      const s = scoreTitle(w.title, w.year);
      return { ...w, band: s.band, score: s.score, reason: s.reason };
    });
    const rank = { "Strong Match": 0, "Possible Match": 1, "Weak Match": 2 };
    scored.sort((a, b) => (rank[a.band] ?? 9) - (rank[b.band] ?? 9) || (b.score - a.score));
    return scored.slice(0, limit);
  }

  /** Factual taste summary — counts and lists, no invented traits. */
  function tasteDNA() {
    const d = data();
    if (!d) return [];
    const s = d.stats || {};
    const rows = [
      { trait: "Films rated", level: `${s.rated ?? 0} · avg ${s.avgRating ?? "—"}★` },
      { trait: "5★ favourites", level: `${s.fiveStar ?? 0} films` },
      { trait: "Rewatched", level: `${s.rewatchCount ?? 0} films` },
      { trait: "Watchlist queued", level: `${s.watchlistCount ?? 0} films` },
    ];
    if (s.topDecade) rows.push({ trait: "Most-watched era", level: s.topDecade });
    return rows;
  }

  function profile() {
    const d = data();
    if (!d) return null;
    return {
      name: d.user?.name || "Me",
      username: d.user?.username || null,
      bio: d.user?.bio || null,
      location: d.user?.location || null,
      memberSince: d.user?.memberSince || null,
      stats: d.stats || {},
      favorites: d.favorites || [],
      tasteDNA: tasteDNA(),
      mostWatched: d.mostWatched || [],
      coldSpots: d.coldSpots || [],
    };
  }

  return {
    profile,
    scoreTitle,
    rankWatchlist,
    findRating,
    watchlistEntry,
    tasteDNA,
    likedTitles,
  };
})();
